-- Separate external competitor evidence from Keyword Planner volume and GSC position.
CREATE TABLE IF NOT EXISTS seo_competitor_evidence(
 id TEXT PRIMARY KEY, cluster TEXT NOT NULL, keyword TEXT NOT NULL, target_path TEXT NOT NULL,
 source TEXT NOT NULL CHECK(source IN ('WEB_RESEARCH','GOOGLE_MANUAL')),
 country TEXT NOT NULL, language TEXT NOT NULL, device TEXT NOT NULL, checked TEXT NOT NULL,
 rank INTEGER CHECK(rank BETWEEN 1 AND 10), result_type TEXT NOT NULL, name TEXT NOT NULL,
 url TEXT NOT NULL, evidence TEXT NOT NULL, opportunity TEXT NOT NULL,
 created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
 CHECK((source='WEB_RESEARCH' AND rank IS NULL) OR (source='GOOGLE_MANUAL' AND rank IS NOT NULL)),
 UNIQUE(source,keyword,country,language,device,checked,url)
);
CREATE INDEX IF NOT EXISTS seo_competitor_cluster ON seo_competitor_evidence(cluster,checked DESC);
INSERT OR IGNORE INTO seo_competitor_evidence(id,cluster,keyword,target_path,source,country,language,device,checked,rank,result_type,name,url,evidence,opportunity) VALUES('seo006c-20261126-01','west','nusa penida west tour','/en/tours/west','WEB_RESEARCH','UNSPECIFIED','en','UNSPECIFIED','2026-11-26',NULL,'OPERATOR','Nusa Penida Transport','https://nusapenidatransport.com/tour/west-nusa-penida-private-driver/','Driver charter, Paluang Cliff and inclusions/exclusions are listed; price unit needs checking.','Show per-car vs per-person rates and confirmed inclusions; clarify optional stops.');
